import { HTMLAttributes } from 'react';
import type * as Stitches from '@stitches/react';
import { config } from '@hexa-ui/theme';

type CSSVariants = Stitches.CSS<typeof config>;
export interface AlertTypes extends HTMLAttributes<HTMLDivElement> {
  type?: 'info' | 'warning' | 'error' | 'success';
  componentVariant?: 'alert' | 'toast';
  css?: CSSVariants;
  message: string;
  actions?: [firstAction: Action, secondAction?: Action];
  showCloseButton?: boolean;
  onClose?(): void;
}

export interface SnackbarTypes extends HTMLAttributes<HTMLDivElement> {
  type: undefined;
  componentVariant?: 'snackbar';
  css?: CSSVariants;
  message: string;
  actions?: [firstAction: Action];
  showCloseButton: undefined;
  onClose?(): undefined;
}

export type AlertProps = SnackbarTypes | AlertTypes;

export type Action = {
  name: string;
  action(): void;
};

export interface StyledContainerTypes extends HTMLAttributes<HTMLDivElement> {
  type?: 'info' | 'warning' | 'error' | 'success';
  componentVariant?: 'alert' | 'toast' | 'snackbar';
  actions?: [firstAction: Action, secondAction?: Action];
}
